async function renderS1Calendar(){
  const {stages,rounds}=await window.cffLoadS1ArchiveJson('ffws-br-2026-s1/dates.json');
  const fragment=document.createDocumentFragment();
  for(const stage of stages){
    const box=document.createElement('section');
    box.className='schedule-box';
    const heading=document.createElement('h3');
    heading.className='schedule-header';
    heading.textContent=stage.name+' · '+stage.date;
    box.append(heading);
    for(const round of rounds.filter(round=>round.stage===stage.key)){
      const row=document.createElement('div'), date=document.createElement('time'), info=document.createElement('span');
      row.className='match-row';
      date.dateTime=round.date;date.textContent=round.dateLabel;
      const groups=round.activeGroups?.length?' · Grupos '+round.activeGroups.join(', '):'';
      info.textContent=round.label+' · '+round.matches+' quedas'+groups;
      row.append(date,info);box.append(row);
    }
    fragment.append(box);
  }
  document.getElementById('schedule-content').replaceChildren(fragment);
  return true;
}
let s1FiltersReady=false;
function initS1Filters(){
  if(s1FiltersReady)return;
  window.buildDayFilters?.();
  const teams=document.getElementById('filter-team-players');
  const days=document.getElementById('filter-player-day');
  for(const name of [...new Set(db.teams.map(team=>team.equipe))].sort())teams?.add(new Option(name,name));
  for(let day=1;day<=TOTAL_DIAS;day++)days?.add(new Option('Dia '+day,day));
  s1FiltersReady=true;
}
async function renderStandaloneS1(page){
  if(page==='datas')return renderS1Calendar();
  if(page==='tabela'||page==='final'){
    await load(S1_ASSETS.stages);
    const render=page==='tabela'?window.cffS1StandaloneRenderClassification:window.cffS1StandaloneRenderFinal;
    const ready=await render();
    if(ready&&page==='tabela')await load(S1_ASSETS.multifilters);
    return ready;
  }
  const sections={
    equipes:['teams','cffS1StaticPagesRender'],
    'comparar-1v1':['compare','cffS1DetailRender'],
    'selecao-da-semana':['selection','cffS1SelectionRender']
  };
  if(sections[page]){
    const [asset,render]=sections[page];
    await load(S1_ASSETS[asset]);
    if(!document.getElementById(page).classList.contains('active'))return false;
    return window[render](page);
  }
  await load(S1_ASSETS.stages);
  await ensureS1Page(page);
  if(!document.getElementById(page).classList.contains('active'))return false;
  initS1Filters();
  if(page==='mvp')window.renderAllPlayers();
  if(page==='notas-cff')window.renderNotasCFFPage();
  if(page==='stats')renderLegacy(page);
  if(page==='stats')armS1StatsCharts();
  return true;
}
async function openStandaloneS1(page){
  const status=document.getElementById('cff-s1-load-status');
  setActive(page);
  status.hidden=s1Rendered.has(page);
  if(status.hidden)return;
  status.textContent='Carregando dados da temporada…';
  if(!s1Renders.has(page)){
    s1Renders.set(page,renderStandaloneS1(page).then(ready=>{
      if(ready)s1Rendered.add(page);
    }).finally(()=>s1Renders.delete(page)));
  }
  try{
    await s1Renders.get(page);
    if(document.getElementById(page).classList.contains('active'))status.hidden=true;
  }catch(error){
    console.error('[S1]',page,error);
    if(document.getElementById(page).classList.contains('active')){
      status.textContent='Não foi possível carregar esta seção. ';
      const retry=document.createElement('button');
      retry.type='button';retry.textContent='Tentar novamente';
      retry.onclick=()=>openStandaloneS1(page);
      status.append(retry);
    }
  }
}
